create or replace function public.set_auth_actor_defaults() returns trigger language plpgsql security invoker set search_path=public as $$ begin if tg_table_name='richieste_urgenti' then if new.created_by_user_id is null and tg_op='INSERT' then new.created_by_user_id := auth.uid(); end if; elsif tg_table_name='interventi' then if new.created_by_user_id is null and tg_op='INSERT' then new.created_by_user_id := auth.uid(); end if; elsif tg_table_name='planning_lavori' then if new.created_by_user_id is null and tg_op='INSERT' then new.created_by_user_id := auth.uid(); end if; elsif tg_table_name='prenotazioni_sale' then if new.created_by_user_id is null and tg_op='INSERT' then new.created_by_user_id := auth.uid(); end if; elsif tg_table_name='import_camere' then if new.uploaded_by_user_id is null and tg_op='INSERT' then new.uploaded_by_user_id := auth.uid(); end if; elsif tg_table_name='camere_lavoro' then new.updated_by_user_id := coalesce(auth.uid(), new.updated_by_user_id); end if; return new; end $$;
drop trigger if exists trg_richieste_urgenti_auth_defaults on public.richieste_urgenti; create trigger trg_richieste_urgenti_auth_defaults before insert or update on public.richieste_urgenti for each row execute function public.set_auth_actor_defaults();
drop trigger if exists trg_interventi_auth_defaults on public.interventi; create trigger trg_interventi_auth_defaults before insert or update on public.interventi for each row execute function public.set_auth_actor_defaults();
