drop trigger if exists trg_prenotazioni_sale_auth_defaults on public.prenotazioni_sale; create trigger trg_prenotazioni_sale_auth_defaults before insert or update on public.prenotazioni_sale for each row execute function public.set_auth_actor_defaults();
drop trigger if exists trg_import_camere_auth_defaults on public.import_camere; create trigger trg_import_camere_auth_defaults before insert or update on public.import_camere for each row execute function public.set_auth_actor_defaults();
drop trigger if exists trg_camere_lavoro_auth_defaults on public.camere_lavoro; create trigger trg_camere_lavoro_auth_defaults before insert or update on public.camere_lavoro for each row execute function public.set_auth_actor_defaults();
